/**
 * The demo's image artifact ("Codex run.png"): a screenshot of SlayZone's desktop app
 * running Codex in a task's terminal, 1072×804 PNG. Kept as base64 in the JS bundle so
 * the demo needs no native asset and no network; the demo hub serves its bytes like a
 * hub serves an uploaded file.
 *
 * Source: `comparison/assets/slayzone-terminals-feature.png`, cropped to the window.
 */
const BASE64 =
  ''

const ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'

/** Base64 to bytes (no `atob`/`Buffer` assumed: Hermes and jest both run this). */
export function decodeBase64(text: string): Uint8Array {
  const clean = text.replace(/=+$/, '')
  const out = new Uint8Array(Math.floor((clean.length * 3) / 4))
  let bits = 0
  let value = 0
  let at = 0
  for (const char of clean) {
    value = (value << 6) | ALPHABET.indexOf(char)
    bits += 6
    if (bits >= 8) {
      bits -= 8
      out[at++] = (value >> bits) & 0xff
    }
  }
  return out
}

let bytes: Uint8Array | null = null

/** The PNG's bytes (decoded once). */
export function demoImageBytes(): Uint8Array {
  bytes ??= decodeBase64(BASE64)
  return bytes
}
